---@param opIndex integer The op index.
---@return CursorType? # The cursor type to display. Returns `nil` if no op exists for this index, or no custom CursorType is set on an existing op.
function ObjType:GetGroundOpCursor(opIndex) end

---Returns the custom CursorType, if any, used for the given op index when the ObjType is shown in an interface
---component.
---@param opIndex integer The op index.
---@return CursorType? # The cursor type to display. Returns `nil` if no op exists for this index, or no custom CursorType is set on an existing op.
function ObjType:GetInterfaceOpCursor(opIndex) end

---Returns the corresponding output value for the given input ParamType.
---@param param ParamType The input param value.
---@return any # The corresponding output value. Returns `param.defaultValue` if the param is not found in the data structure.
function ObjType:GetParamValue(param) end

---Returns whether this config contains output data for the given input ParamType.
---@param param ParamType The input param value.
---@return boolean # Whether a corresponding value exists in this config for ParamType.
function ObjType:HasParam(param) end

---Determines how individual objects stack with objects of the same type.
---@enum ObjStackType
ObjStackType = {
    ---Objects of this type will stack only in Inventories that allow stacking.
    SOMETIMES = 0,
    ---Objects of this type stack at all times.
    ALWAYS = 1,
    ---Objects of this type can never be stacked. This type is always used for objects with ObjVars.
    NEVER = 2,
}
